def check_n4():
    a = [0, 1, 2, 4]
    n = 4

    # Calculate all pairwise sums
    sums = set()
    for i in range(n):
        for j in range(i + 1, n):
            sums.add(a[i] + a[j])

    # Check if the set matches {1, 2, ..., n(n-1)/2}
    required_max = n * (n - 1) // 2
    required_set = set(range(1, required_max + 1))

    print(f"Achieved sums: {sorted(list(sums))}")
    print(f"Required sums: {sorted(list(required_set))}")

    if sums == required_set:
        return True
    else:
        return False

print(check_n4())

